mapper.select:
select v.chunk_id as "chunkId",
       (1 - (v.embedding <=> cast(#{queryVector} as vector))) as score
  from kb_vector_${dim} v
 where v.kb_id = #{kbId}
 order by v.embedding <=> cast(#{queryVector} as vector)
 limit #{topK}

mapper.delete:
delete from kb_vector_${dim}
 where chunk_id in

    #{id}
